import express from 'express';
import { carrinhorouter } from './routes/carrinho.js';
import cors from 'cors';

const app = express();
const port = 3000;  

app.use(express.json());
app.use(cors());

app.use('/api', carrinhorouter);

app.listen(port, () => {
  console.log(`Server is running at http://localhost:${port}`);
});
